function toast(message){$("#toast").textContent=message;$("#toast").classList.add("visible");setTimeout(()=>$("#toast").classList.remove("visible"),5000);}
async function api(path,{method="GET",body}={}){
 let r;try{r=await fetch("/api"+path,{method,credentials:"same-origin",headers:{"Content-Type":"application/json",...(S.me?{"X-CSRF-Token":S.me.csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});}catch{throw new Error(T("network_error"));}
 let data;try{data=await r.json();}catch{throw new Error(T("service_unavailable"));}
 if(!r.ok)throw new Error(T(data.detail||"service_unavailable"));return data;
}
function modal(title,body){$("#dialog-content").innerHTML='<div class="modal-heading"><h2>'+esc(title)+'</h2><button class="close" data-action="close" aria-label="'+esc(L("Đóng","Close"))+'">×</button></div>'+body;$("#dialog").showModal();}
function options(items,labelKey="name"){return items.map(x=>'<option value="'+esc(x.id)+'">'+esc(typeof labelKey==="function"?labelKey(x):x[labelKey])+'</option>').join("");}
function field(label,name,type="text",value="",extra=""){return '<label class="field">'+esc(label)+'<input name="'+esc(name)+'" type="'+esc(type)+'" value="'+esc(value)+'" '+extra+' required></label>';}
function area(label,name,extra=""){return '<label class="field">'+esc(label)+'<textarea name="'+esc(name)+'" '+extra+' required></textarea></label>';}
function select(label,name,opts,required=true){return '<label class="field">'+esc(label)+'<select name="'+esc(name)+'" '+(required?"required":"")+'><option value="">'+esc(L("Chọn…","Choose…"))+'</option>'+opts+'</select></label>';}
function classSelect(optional=false){return select(T("class"),"class_id",(optional?'<option value="">'+esc(L("Toàn tổ chức","Whole organization"))+'</option>':"")+options(S.data.classes||[]),!optional);}
function personSelect(name="student_id",kind="student"){return select(T(kind),name,options((S.data.users||[]).filter(x=>x.role===kind),"display_name"));}
function form(kind,fields,help=""){return '<form data-form="'+kind+'" class="form-grid">'+(help?'<p class="form-help">'+esc(help)+'</p>':"")+fields+'<div class="form-error"></div><div class="form-actions">'+btn(T("cancel"),"close","","secondary")+'<button type="submit" class="btn">'+esc(T("save"))+'</button></div></form>';}
function navItems(){if(S.me.role==="student")return ["home","library","classes","assignments","evidence","notes","resources","announcements"];if(S.me.role==="teacher")return ["home","classes","attendance","assignments","feedback","resources","announcements"];if(S.me.role==="partner_admin")return ["home","people","classes","library","assignments","analytics","payments","announcements","resources"];return ["home","support"];}
function shell(content){
 document.documentElement.lang=S.locale;const nav=navItems();
 $("#app").innerHTML='<aside class="sidebar">'+brand()+'<div class="nav-label">'+esc(L("KHÔNG GIAN HỌC TẬP","YOUR LEARNING SPACE"))+'</div><nav aria-label="'+esc(L("Điều hướng","Navigation"))+'">'+nav.map(k=>'<button class="nav-item '+(S.view===k?"active":"")+'" data-view="'+k+'" '+(S.view===k?'aria-current="page"':"")+'>'+I(k)+esc(T(k))+'</button>').join("")+'</nav><div class="sidebar-foot">'+I("spark")+'<strong>'+esc(L("Mỗi bước nhỏ đều có ý nghĩa.","Every small step matters."))+'</strong><p>'+esc(L("Khám phá · Luyện tập · Sáng tạo · Nhìn lại","Discover · Practise · Create · Reflect"))+'</p>'+btn(T("support"),"support","","quiet small")+'</div></aside><div class="workspace"><header class="topbar"><span class="mobile-brand">Career Compass</span><div class="organization-name"><strong>'+esc(S.org.name)+'</strong><br><small class="muted">'+esc(T(S.me.role))+'</small></div><div class="row"><button class="locale" data-action="locale">'+(S.locale==="vi-VN"?"VI · English":"EN · Tiếng Việt")+'</button><div class="avatar" aria-hidden="true">'+esc(S.me.display_name.slice(0,1))+'</div><button class="btn quiet small" data-action="logout" aria-label="'+esc(L("Đăng xuất","Sign out"))+'">'+I("logout")+'</button></div></header><main id="main" class="content">'+content+'</main></div>';
}
