function shuffle(a){return [...a].sort(()=>Math.random()-.5);}
async function openBook(id,lessonId=null){
 const b=await api("/books/"+id);S.book=b;S.view="library";
 if(!b.lessons.length){shell(heading(local(b.book.title),L("Nội dung đang được chuẩn bị.","Content is being prepared.")));return;}
 await openLesson(lessonId||b.lessons[0].id);
}
async function openLesson(id){
 S.lesson=await api("/lessons/"+id);renderLesson();$("#main").scrollIntoView({behavior:"instant"});
}
function renderLesson(){
 const b=S.book,l=S.lesson.lesson,acts=S.lesson.activities,c=l.content||{},isStudent=S.me.role==="student";
 const navigation='<aside class="unit-nav" aria-label="'+esc(L("Các bài trong sách","Book lessons"))+'">'+b.units.map(u=>'<details '+(u.id===l.unit_id?"open":"")+'><summary>'+esc(local(u.title))+'</summary>'+b.lessons.filter(x=>x.unit_id===u.id).map(x=>'<button data-action="lesson" data-id="'+x.id+'" class="lesson-link '+(x.id===l.id?"active":"")+'">'+String(x.ordinal).padStart(2,"0")+' · '+esc(local(x.title))+'</button>').join("")+'</details>').join("")+'</aside>';
 const vocab=(c.vocabulary||[]).map(v=>'<div class="vocab-card"><div class="vocab-picture" role="img" aria-label="'+esc(v.en)+'">'+esc(v.picture||wordArt[v.en.toLowerCase()]||"💬")+'</div><strong lang="en-PH">'+esc(v.en)+'</strong><small lang="vi-VN">'+esc(v.vi)+'</small><button class="btn quiet" data-action="speak" data-text="'+esc(v.en)+'">'+I("sound")+esc(L("Nghe từ","Hear the word"))+'</button></div>').join("");
 const models=(c.models||[]).map((m,i)=>'<div class="speech"><span class="speech-face" aria-hidden="true">'+(i%2?"👦":"👧")+'</span><div class="bubble"><strong lang="en-PH">'+esc(m.en)+'</strong><p lang="vi-VN">'+esc(m.vi)+'</p><button class="btn quiet small" data-action="speak" data-text="'+esc(m.en)+'">'+I("sound")+esc(L("Nghe mẫu","Hear the model"))+'</button></div></div>').join("");
 const lessons=b.lessons,ix=lessons.findIndex(x=>x.id===l.id);
 const content='<div class="row between wrap">'+btn(L("← Về tủ sách","← Back to books"),"back-library","","secondary small")+badge(local(b.book.title),"blue")+'</div><div class="lesson-layout">'+navigation+'<div class="lesson-main"><header class="lesson-banner"><span class="eyebrow">'+esc(L("CÙNG KHÁM PHÁ","LET’S DISCOVER"))+' · '+String(l.ordinal).padStart(2,"0")+'</span><h1>'+esc(local(l.title))+'</h1><p class="muted">'+esc(local(c.objective))+'</p><div class="steps">'+[L("Nhìn & nghe","Look & listen"),L("Nói theo mẫu","Try speaking"),L("Tự mình thử","Make it yours"),L("Nhìn lại","Reflect")].map(x=>'<span>'+esc(x)+'</span>').join("")+'</div></header>'+
 (c.story?'<section class="card"><h2>'+esc(L("Câu chuyện của hôm nay","Today’s story"))+'</h2><div class="story">'+esc(local(c.story))+'</div></section>':"")+
 (c.key_idea?'<div class="key-idea">'+esc(local(c.key_idea))+'</div>':"")+
 (vocab?'<section class="card"><h2>'+esc(L("Nhìn, nghe và nói","Look, listen and say"))+'</h2><p class="muted">'+esc(L("Bấm vào nút nghe từ. Em có thể chỉ tranh trước khi nói.","Tap to hear a word. You can point before you speak."))+'</p><div class="vocab-grid">'+vocab+'</div></section>':"")+
 (models?'<section class="card"><h2>'+esc(L("Cùng tập nói","My speaking model"))+'</h2><div class="conversation">'+models+'</div><p class="review-scope">'+esc(L("Đổi vai và thử lại. Thay một từ để nói về ý tưởng của em.","Swap roles and try again. Change a word to make it your own."))+'</p></section>':"")+
 '<section class="card"><h2>'+esc(L("Thử một chút nhé!","Give it a try!"))+'</h2><p class="review-scope">'+esc(isStudent?L("Câu hỏi có đáp án sẽ được kiểm tra. Nói, vẽ và dự án được gửi để thầy cô xem.","Questions with an answer key are checked. Speaking, drawing and projects go to your teacher for review."):L("Chế độ xem của giáo viên / quản trị viên. Học sinh gửi bài từ tài khoản của mình.","Teacher / administrator view. Students submit from their own accounts."))+'</p>'+acts.map(activityHTML).join("")+'</section>'+
 '<section class="card"><h2>'+esc(L("Trang sách đi cùng bài học","The book behind this lesson"))+'</h2><div class="row wrap">'+l.source_pages.map(p=>btn(L("Trang ","Page ")+p,"source",p,"secondary small")).join("")+'</div><p class="review-scope">'+esc(L("Nội dung chữ đã được chuyển thể thành hoạt động. Tranh gốc sẽ được hiển thị khi bản minh họa được nhập vào hệ thống.","Text has been adapted into activities. Original artwork will display when illustration assets are imported."))+'</p></section>'+
 '<div class="row between">'+(ix>0?btn(L("← Bài trước","← Previous"),"lesson",lessons[ix-1].id,"secondary"):"<span></span>")+(ix<lessons.length-1?btn(L("Bài tiếp theo →","Next lesson →"),"lesson",lessons[ix+1].id):btn(L("Về hành trình","Back to journey"),"back-home"))+'</div></div></div>';
 shell(content);document.querySelectorAll("canvas.draw-canvas").forEach(setupDrawing);
}
function activityHTML(a){
 const p=a.payload||{},status=S.lesson.attempts.filter(x=>x.activity_id===a.id).at(-1);
 let body="";
 if(a.kind==="choice"){body='<div class="choice-grid">'+shuffle(p.options||[]).map(o=>'<label class="choice-option"><input type="radio" name="answer" value="'+esc(o.id)+'" required><span>'+esc(local(o.label))+'</span></label>').join("")+'</div>';}
 else if(a.kind==="match"){const opts=shuffle(p.right||[]);body=(p.left||[]).map(x=>'<label class="match-row"><span lang="en-PH">'+esc(x.label)+'</span><select name="match_'+esc(x.id)+'" required><option value="">'+esc(L("Chọn nghĩa","Choose meaning"))+'</option>'+opts.map(o=>'<option value="'+esc(o.id)+'">'+esc(local(o.label))+'</option>').join("")+'</select></label>').join("");}
 else if(a.kind==="sequence"){body='<div class="sentence-tray" aria-live="polite" data-tray="'+a.id+'"></div><div class="word-bank">'+shuffle((p.words||[]).map((word,i)=>({word,id:i}))).map(w=>'<button type="button" class="word-token" data-action="word" data-id="'+a.id+'" data-index="'+w.id+'" data-word="'+esc(w.word)+'">'+esc(w.word)+'</button>').join("")+'</div>'+btn(L("Làm lại thứ tự","Reset order"),"reset-sequence",a.id,"quiet small");}
 else if(a.kind==="speaking"){body='<p class="form-help">'+esc(L("Nói với bạn, thầy cô hoặc người lớn tin cậy. Ứng dụng không ghi âm em.","Speak with a friend, teacher, or trusted adult. This activity does not record audio."))+'</p><label class="choice-option"><input type="checkbox" name="practised" required>'+esc(L("Em đã thử nói theo mẫu.","I tried saying the model."))+'</label>';}
 else if(a.kind==="drawing"){body='<canvas class="draw-canvas" width="600" height="300" data-drawing="'+a.id+'" aria-label="'+esc(L("Ô vẽ ý tưởng; có thể dùng hoạt động viết thay thế.","Drawing space; the written activity is an alternative."))+'"></canvas>'+btn(L("Xóa nét cuối","Undo last stroke"),"undo-drawing",a.id,"quiet small");}
 else body='<textarea name="text" maxlength="5000" required aria-label="'+esc(local(a.prompt))+'" placeholder="'+esc(local(p.frame)||L("Em có thể dùng tiếng Việt trước, rồi thử một từ tiếng Anh.","You can use Vietnamese first, then try an English word."))+'"></textarea>';
 return '<form class="activity" data-form="activity" data-id="'+a.id+'" data-kind="'+a.kind+'"><div class="row between wrap"><h3>'+esc(local(a.prompt))+'</h3>'+(status?badge(T(status.status),status.correct===false?"amber":""):"")+'</div><p class="instructions">'+esc(local(p.instructions))+'</p>'+body+'<div class="form-error"></div><div class="response-result" aria-live="polite"></div>'+(S.me.role==="student"?'<button type="submit" class="btn small">'+esc(L("Lưu lượt thử của em","Save my attempt"))+'</button>':"")+'</form>';
}
function setupDrawing(canvas){
 const key=canvas.dataset.drawing,ctx=canvas.getContext("2d");if(!drawings.has(key))drawings.set(key,[]);
 let active=false,current=null;
 const point=ev=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(600,Math.round((ev.clientX-r.left)*600/r.width))),Math.max(0,Math.min(300,Math.round((ev.clientY-r.top)*300/r.height)))];};
 canvas.addEventListener("pointerdown",ev=>{if(S.me.role!=="student"||drawings.get(key).length>=100)return;active=true;current=[point(ev)];drawings.get(key).push(current);canvas.setPointerCapture(ev.pointerId);});
 canvas.addEventListener("pointermove",ev=>{if(!active)return;if(drawings.get(key).reduce((n,s)=>n+s.length,0)>=2000)return;current.push(point(ev));paintDrawing(canvas,drawings.get(key));});
 for(const event of ["pointerup","pointercancel"])canvas.addEventListener(event,()=>{active=false;paintDrawing(canvas,drawings.get(key));});
 paintDrawing(canvas,drawings.get(key));
}
function paintDrawing(canvas,strokes){const ctx=canvas.getContext("2d");ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle="#167867";ctx.lineWidth=4;ctx.lineCap="round";ctx.lineJoin="round";for(const s of strokes){if(!s.length)continue;ctx.beginPath();ctx.moveTo(...s[0]);for(const p of s.slice(1))ctx.lineTo(...p);if(s.length===1)ctx.lineTo(s[0][0]+.2,s[0][1]+.2);ctx.stroke();}}
function openForm(action,id){
 const classes=S.data.classes||[];
 if(action==="activate")return modal(L("Kích hoạt tài khoản","Activate your account"),form("activate",field(L("Mã trường / trung tâm","School / center code"),"organization")+field(L("Tên đăng nhập","Username"),"username")+field(L("Mã kích hoạt","Activation code"),"activation_code")+field(L("Mật khẩu mới","New password"),"password","password","","minlength=8 maxlength=72 autocomplete=new-password"),L("Dùng mã do quản trị viên cấp. Học sinh: tối thiểu 8 ký tự; giáo viên: tối thiểu 12. Mã chỉ dùng một lần.","Use the code from your administrator. Students: at least 8 characters; teachers: at least 12. Codes work once.")));
 if(action==="register")return modal(L("Bắt đầu với tổ chức của bạn","Set up your organization"),form("register",field(L("Mã mời đối tác","Partner invitation"),"invitation")+field(L("Tên trường / trung tâm","School / center name"),"organization_name")+field(L("Mã tổ chức (chữ thường, không dấu)","Organization code (lowercase, no spaces)"),"organization","text","","pattern=[a-z0-9-]{3,48}")+select(L("Loại tổ chức","Organization type"),"kind",options([{id:"school",name:L("Trường học","School")},{id:"center",name:L("Trung tâm đào tạo","Training center")},{id:"organization",name:L("Tổ chức","Organization")}]))+field(L("Tên đăng nhập quản trị","Administrator username"),"username")+field(L("Mật khẩu (ít nhất 12 ký tự)","Password (at least 12 characters)"),"password","password","","minlength=12 maxlength=72 autocomplete=new-password")));
 if(action==="class-form")return modal(L("Lớp học mới","New class"),form("class",field(T("name"),"name")+field(L("Lịch học","Class schedule"),"schedule")+select(L("Độ tuổi","Age group"),"age_band",options(["4-6","7-12","13-18"].map(id=>({id,name:id}))))));
 if(action==="person-form")return modal(L("Tạo tài khoản có kiểm soát","Create a managed account"),form("person",field(L("Biệt danh học tập / tên hiển thị","Learning alias / display name"),"display_name")+select(L("Vai trò","Role"),"role",options([{id:"student",name:T("student")},{id:"teacher",name:T("teacher")}]))+classSelect(),L("Không cần email, ngày sinh hay thông tin nhạy cảm của học sinh. Tài khoản sẽ có mã kích hoạt một lần.","No student email, date of birth or sensitive details are needed. The account receives a one-time activation code.")));
 if(action==="membership-form")return modal(L("Thêm thành viên / phân công","Add member / assignment"),form("membership",classSelect()+select(L("Tài khoản","Account"),"user_id",options(S.data.users.filter(x=>["student","teacher"].includes(x.role)),x=>x.display_name+" · "+T(x.role)))+select(L("Vai trò trong lớp","Class role"),"kind",options([{id:"student",name:T("student")},{id:"teacher",name:T("teacher")}]))));
 if(action==="enroll-form")return modal(L("Ghi danh sách học","Enroll in a book"),form("enroll",classSelect()+personSelect()+select(T("book"),"book_id",options(S.catalog,x=>local(x.title))),L("Học sinh cần là thành viên của lớp trước khi ghi danh.","The student must be a class member before enrollment.")));
 if(action==="attendance-form")return modal(T("attendance"),form("attendance",classSelect()+personSelect()+field(L("Ngày học","Session date"),"session_date","date",new Date().toLocaleDateString("en-CA"))+select(T("status"),"status",options(["present","absent","late","excused"].map(id=>({id,name:T(id)}))))));
 if(action==="assignment-form")return modal(L("Giao nhiệm vụ mới","Create a new assignment"),form("assignment",classSelect()+field(T("title"),"title")+area(L("Hướng dẫn","Instructions"),"instructions")+field(L("Hạn nộp","Due"),"due_at","datetime-local")));
 if(action==="submission-form")return modal(L("Chia sẻ bài làm","Share your work"),form("submission",'<input type="hidden" name="assignment_id" value="'+esc(id)+'">'+area(L("Bài làm hoặc lời giải thích","Your work or explanation"),"body")+'<label class="field">'+esc(L("Tệp tùy chọn · tối đa 1 MB","Optional file · up to 1 MB"))+'<input type="file" name="attachment"></label>',L("Chỉ gửi sản phẩm học tập em muốn chia sẻ với thầy cô. Không gửi giấy tờ cá nhân.","Share learning work you want your teacher to see. Do not upload personal documents.")));
 if(action==="feedback-form"){const c=S.data.capsules.find(x=>x.id===id);return modal(L("Nhận xét để hỗ trợ bước tiếp theo","Feedback for the next step"),form("feedback",(c?'<input type="hidden" name="class_id" value="'+c.class_id+'"><input type="hidden" name="student_id" value="'+c.student_id+'"><input type="hidden" name="capsule_id" value="'+c.id+'"><p>'+esc(userName(c.student_id))+' · '+esc(className(c.class_id))+'</p>':classSelect()+personSelect())+field(L("Kỹ năng đang luyện","Skill in focus"),"skill")+area(L("Hành động đã quan sát được","Observed action"),"observed_action")+area(L("Bước luyện tập tiếp theo","Next practice step"),"next_step"),L("Dựa vào sản phẩm cụ thể. Không xếp hạng hoặc gán nhãn nghề nghiệp cho trẻ.","Use specific evidence. Do not rank children or assign career labels.")));}
 if(action==="note-form")return modal(L("Một ý tưởng mới","A new idea"),form("note",field(T("title"),"title")+area(L("Em đang nghĩ gì?","What are you thinking about?"),"body")));
 if(action==="announcement-form")return modal(L("Thông báo mới","New announcement"),form("announcement",classSelect(S.me.role==="partner_admin")+field(T("title"),"title")+area(T("body"),"body")));
 if(action==="resource-form")return modal(L("Tài nguyên mới","New resource"),form("resource",classSelect(S.me.role==="partner_admin")+field(T("title"),"title")+field(L("Đường dẫn HTTPS","HTTPS link"),"url","url")+select(L("Loại tài nguyên","Type"),"kind",options([{id:"document",name:L("Tài liệu","Document")},{id:"video",name:"Video"},{id:"link",name:L("Liên kết","Link")}]))));
 if(action==="payment-form")return modal(L("Khoản phải thu","Payment record"),form("payment",personSelect()+field(L("Nội dung khoản thu","Payment description"),"label")+field(L("Số tiền (VND)","Amount (VND)"),"amount_vnd","number","","min=0 max=1000000000 step=1")));
 if(action==="receipt-form")return modal(L("Xác nhận đã nhận thanh toán","Confirm payment received"),form("receipt",'<input type="hidden" name="payment_id" value="'+esc(id)+'">'+field(L("Mã biên nhận / tham chiếu","Receipt / reference"),"reference"),L("Chỉ xác nhận sau khi đã kiểm tra tiền nhận. Đây là ghi nhận thủ công, không phải thanh toán trực tuyến.","Confirm only after checking funds received. This is a manual record, not an online checkout.")));
 if(action==="support")return modal(T("support"),form("support",select(L("Chủ đề","Topic"),"category",options([{id:"access",name:L("Tài khoản","Account access")},{id:"learning",name:L("Việc học","Learning")},{id:"content",name:L("Nội dung sách","Book content")},{id:"technical",name:L("Kỹ thuật","Technical")}]))+area(L("Bạn cần hỗ trợ gì?","How can we help?"),"message")));
}
function activationResult(r){modal(L("Tài khoản đã sẵn sàng để kích hoạt","Account ready for activation"),'<div class="stack"><p class="success">'+esc(L("Gửi riêng thông tin này cho học sinh / người giám hộ hoặc giáo viên.","Share these details privately with the student / guardian or teacher."))+'</p><p><strong>'+esc(L("Mã tổ chức: ","Organization: "))+'</strong>'+esc(S.org.slug)+'</p><p><strong>'+esc(L("Tên đăng nhập: ","Username: "))+'</strong>'+esc(r.username)+'</p><p>'+esc(L("Mã kích hoạt một lần, hiệu lực 24 giờ:","One-time activation code, valid for 24 hours:"))+'</p><div class="activation-code">'+esc(r.activation_code)+'</div><p class="form-help">'+esc(L("Người học vào “Kích hoạt tài khoản” để tự đặt mật khẩu. Không gửi mã vào thông báo của lớp.","The learner chooses “Activate account” and sets their own password. Do not put the code in class announcements."))+'</p>'+btn(L("Đã ghi lại, đóng","Saved, close"),"close")+'</div>');}
async function refresh(){S.data=await api("/dashboard");}
async function start(){try{const me=await api("/me");S.me=me.user;S.org=me.organization;await refresh();S.catalog=await api("/catalog");renderView();}catch(e){S.me=null;landing();}}
document.addEventListener("click",async event=>{
 const el=event.target.closest("button,a[data-action]");if(!el)return;
 if(el.dataset.view){S.view=el.dataset.view;return renderView();}
 if(el.dataset.portal){S.portal=el.dataset.portal;return landing();}
 const action=el.dataset.action,id=el.dataset.id;if(!action)return;
 try{
  if(action==="close"){return $("#dialog").close();}
  if(action==="locale"){S.locale=S.locale==="vi-VN"?"en-PH":"vi-VN";localStorage.setItem("cc-locale",S.locale);return S.lesson?renderLesson():S.me?renderView():landing();}
  if(action==="logout"){await api("/logout",{method:"POST",body:{}});S.me=null;S.data={};drawings.clear();return landing();}
  if(action==="book")return await openBook(id);
  if(action==="lesson")return await openLesson(id);
  if(action==="back-library"){S.view="library";return renderView();}
  if(action==="back-home"){S.view="home";return renderView();}
  if(action==="enroll-help")return toast(T("not_enrolled"));
  if(action==="speak"){if(!("speechSynthesis" in window))return toast(L("Thiết bị chưa hỗ trợ đọc. Em có thể nhờ thầy cô đọc mẫu.","This device cannot read aloud. Ask your teacher for a model."));speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(el.dataset.text);u.lang="en-PH";u.rate=.78;speechSynthesis.speak(u);return;}
  if(action==="word"){const tray=document.querySelector('[data-tray="'+id+'"]');tray.dataset.order=(tray.dataset.order?tray.dataset.order+",":"")+el.dataset.index;const span=document.createElement("span");span.textContent=el.dataset.word;span.className="word-token";tray.append(span);el.disabled=true;return;}
  if(action==="reset-sequence"){const fm=el.closest("form");const tray=fm.querySelector(".sentence-tray");tray.textContent="";tray.dataset.order="";fm.querySelectorAll('[data-action="word"]').forEach(x=>x.disabled=false);return;}
  if(action==="undo-drawing"){drawings.get(id)?.pop();paintDrawing(document.querySelector('[data-drawing="'+id+'"]'),drawings.get(id)||[]);return;}
  if(action==="source"){const p=await api("/books/"+S.book.book.id+"/pages/"+id);return modal(L("Trang nguồn ","Source page ")+id,'<div class="review-body">'+(p.source_text?'<div class="source-text">'+esc(p.source_text)+'</div>':'<p>'+esc(L("Trang này là tranh minh họa. Tệp tranh cần được nhập vào hệ thống.","This page contains illustration artwork. The image asset still needs to be imported."))+'</p>')+'</div>');}
  if(action==="reset"){return modal(L("Đặt lại quyền truy cập?","Reset account access?"),'<p>'+esc(L("Phiên đăng nhập hiện tại của tài khoản này sẽ kết thúc. Một mã kích hoạt mới sẽ được cấp.","Current sessions for this account will end. A new activation code will be issued."))+'</p><div class="form-actions">'+btn(T("cancel"),"close","","secondary")+btn(L("Cấp mã mới","Issue new code"),"confirm-reset",id)+'</div>');}
  if(action==="confirm-reset"){$("#dialog").close();const r=await api("/people/"+id+"/reset",{method:"POST",body:{}});return activationResult(r);}
  if(action==="roster"){const ids=S.data.memberships.filter(m=>m.class_id===id).map(m=>m.student_id);return modal(className(id),table([T("student"),L("Tên đăng nhập","Username")],S.data.users.filter(u=>ids.includes(u.id)).map(u=>'<tr><td>'+esc(u.display_name)+'</td><td>'+esc(u.username)+'</td></tr>').join("")));}
  if(action==="submissions"){const items=S.data.submissions.filter(s=>s.assignment_id===id);return modal(L("Bài đã nộp","Submissions"),'<div class="stack">'+(items.length?items.map(s=>'<article class="list-item"><h3>'+esc(userName(s.student_id))+'</h3><p>'+esc(s.body)+'</p>'+(s.attachment_name?'<a class="btn secondary small" href="/api/submissions/'+s.id+'/attachment" download>'+esc(L("Tải tệp: ","Download: ")+s.attachment_name)+'</a>':"")+'</article>').join(""):empty(L("Chưa có bài nộp.","No submissions yet.")))+'</div>');}
  if(action==="attempt-detail"){const a=await api("/attempts/"+id);let text= a.response.text|| (a.response.practised?L("Em đã thử nói theo mẫu.","I tried speaking the model."):a.response.answer?JSON.stringify(a.response.answer):"");modal(L("Sản phẩm học tập","Learning work"),'<p class="date">'+formatDate(a.created_at)+'</p><div class="review-body">'+esc(text)+'</div>'+(a.response.strokes?'<canvas id="review-drawing" class="draw-canvas" width="600" height="300"></canvas>':""));if(a.response.strokes)paintDrawing($("#review-drawing"),a.response.strokes);return;}
  if(action==="export"){const data=await api("/evidence/export");const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:"application/json"}));const a=document.createElement("a");a.href=url;a.download="my-learning-evidence.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(action==="workflow"){const key={student:"student_learning",teacher:"teacher_support",partner_admin:"partner_operations",content_editor:"book_content",platform_support:"platform_support"}[S.me.role];const r=await api("/workflows",{method:"POST",body:{workflow:key,locale:S.locale}});if(r.next_lessons?.length){const n=r.next_lessons[0];return await openBook(n.book_id,n.lesson_id);}const detail=S.me.role==="partner_admin"?'<p>'+esc(L("Lớp chưa có giáo viên: ","Classes without a teacher: "))+(r.classes_without_teacher?.length||0)+'</p><p>'+esc(L("Học sinh chưa ghi danh sách: ","Students without a book: "))+(r.students_without_book?.length||0)+'</p>':"";return modal(L("Bước tiếp theo","Your next step"),'<div class="stack"><p>'+esc(local(r.message))+'</p>'+detail+btn(L("Tiếp tục","Continue"),"close")+'</div>');}
  if(action==="report"){const feedback=S.data.feedback;return modal(L("Ghi nhận tiến bộ cho phụ huynh","Progress report for parents"),'<div class="print-report"><p>'+esc(S.org.name)+' · '+formatDate(new Date())+'</p><p class="form-help">'+esc(L("Bản ghi nhận dựa trên các nhận xét gần đây. Đánh giá sáu tháng cần đối chiếu sản phẩm đầu kỳ và cuối kỳ cùng học sinh và người lớn.","This report uses recent feedback. A six-month review needs early and recent work, discussed with the learner and a trusted adult."))+'</p>'+feedback.map(x=>'<article class="review-period"><h3>'+esc(userName(x.student_id))+' · '+esc(x.skill)+'</h3><p class="date">'+formatDate(x.created_at)+'</p><p>'+esc(x.observed_action)+'</p><p><strong>'+esc(L("Luyện tập tiếp: ","Next practice: "))+'</strong>'+esc(x.next_step)+'</p></article>').join("")+btn(L("In / lưu PDF","Print / save PDF"),"print")+'</div>');}
  if(action==="print")return window.print();
  openForm(action,id);
 }catch(e){toast(e.message);}
});
document.addEventListener("submit",async ev=>{
 const fm=ev.target.closest("form[data-form]");if(!fm)return;ev.preventDefault();
 const submit=fm.querySelector('[type="submit"]');submit.disabled=true;
 const error=fm.querySelector(".form-error");error.textContent="";error.className="form-error";
 const data=Object.fromEntries(new FormData(fm)),kind=fm.dataset.form;
 try{
  if(kind==="login"){await api("/login",{method:"POST",body:data});return await start();}
  if(kind==="activate"){await api("/activate",{method:"POST",body:data});$("#dialog").close();toast(L("Đã kích hoạt. Bây giờ em có thể đăng nhập.","Activated. You can now sign in."));return;}
  if(kind==="register"){data.invitation=data.invitation.trim();await api("/register-partner",{method:"POST",body:data});$("#dialog").close();toast(L("Tổ chức đã được tạo. Hãy đăng nhập.","Your organization is ready. Please sign in."));return;}
  if(kind==="activity"){
   const a=S.lesson.activities.find(x=>x.id===fm.dataset.id);let response={};
   if(a.kind==="choice")response={answer:data.answer};
   else if(a.kind==="match")response={answer:Object.fromEntries(Object.entries(data).filter(([k])=>k.startsWith("match_")).map(([k,v])=>[k.slice(6),v]))};
   else if(a.kind==="sequence"){const order=fm.querySelector(".sentence-tray").dataset.order;if(!order||order.split(",").length!==(a.payload.words||[]).length)throw new Error(L("Hãy dùng hết các từ.","Use all the words."));response={answer:order.split(",").map(Number)};}
   else if(a.kind==="speaking")response={practised:data.practised==="on"};
   else if(a.kind==="drawing")response={strokes:drawings.get(a.id)||[]};
   else response={text:data.text};
   const en=(S.data.enrollments||[]).find(x=>x.student_id===S.me.id&&x.book_id===a.book_id&&x.active);
   if(!en)throw new Error(T("not_enrolled"));
   const serialized=JSON.stringify(response);
   if(fm.dataset.lastResponse!==serialized){fm.dataset.idempotency=crypto.randomUUID();fm.dataset.lastResponse=serialized;}
   const r=await api("/attempts",{method:"POST",body:{enrollment_id:en.id,activity_id:a.id,idempotency_key:fm.dataset.idempotency,response}});
   fm.querySelector(".response-result").textContent=r.correct===false?L("Chưa đúng lần này. Xem lại từ và thử thêm nhé!","Not yet. Look at the words and try again!"):r.correct===true?L("Em đã làm đúng! Thử nói lại bằng lời của em nhé.","That’s correct! Try saying it in your own words."):L("Đã lưu lượt thử. Thầy cô có thể xem và hỗ trợ em.","Your attempt is saved. Your teacher can review and support you.");
   await refresh();return;
  }
  let endpoint;
  if(["person","membership","enroll","attendance","assignment","feedback","announcement","resource"].includes(kind)&&"class_id" in data&&!data.class_id)data.class_id=null;
  const mapping={class:"/classes",person:"/people",membership:"/memberships",enroll:"/enrollments",attendance:"/attendance",assignment:"/assignments",submission:"/submissions",feedback:"/feedback",announcement:"/announcements",resource:"/resources",note:"/notes",payment:"/payments",support:"/support"};
  endpoint=mapping[kind];
  if(kind==="assignment"){data.locale=S.locale;data.due_at=data.due_at?new Date(data.due_at).toISOString():null;}
  if(kind==="feedback")data.locale=S.locale;
  if(kind==="payment")data.amount_vnd=Number(data.amount_vnd);
  if(kind==="receipt"){endpoint="/payments/"+data.payment_id+"/confirm";delete data.payment_id;}
  if(kind==="submission"){const file=new FormData(fm).get("attachment");delete data.attachment;if(file?.size){if(file.size>1048576)throw new Error(T("file_too_large"));data.attachment_name=file.name;data.attachment_base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]);reader.onerror=()=>reject(new Error(T("invalid_input")));reader.readAsDataURL(file);});}}
  const result=await api(endpoint,{method:"POST",body:data});$("#dialog").close();await refresh();renderView();
  if(kind==="person")activationResult(result);else toast(L("Đã lưu thành công.","Saved successfully."));
 }catch(e){error.textContent=e.message;error.className="form-error error";}
 finally{submit.disabled=false;}
});
start();
